import{_ as a}from"./chunks/stairs-terms.BigRb0h7.js";import{_ as d,o as e,c as r,a5 as o}from"./chunks/framework.BYXPg_yw.js";const u=JSON.parse('{"title":"계단과 단차","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/operation/stairs.md","filePath":"ko/manual/operation/stairs.md","lastUpdated":1792139892000}'),i={name:"ko/manual/operation/stairs.md"};function s(n,t,l,c,h,m){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="계단과-단차" tabindex="-1">계단과 단차 <a class="header-anchor" href="#계단과-단차" aria-label="Permalink to &quot;계단과 단차&quot;">​</a></h1><p>RBQ가 넘을 수 있는 단의 높이는 어떤 <strong>보행</strong>을 쓰는지, 계단에 <strong>챌판</strong>이 있는지, 디딤판이 단 높이에 비해 얼마나 <strong>깊은지</strong>에 따라 달라집니다. 이 페이지는 보행별 한계와 그 한계가 성립하는 조건을 정리합니다. <a href="/RBQ/nightly/ko/manual/product-descriptions/general-specification.html">기본 사양</a> 페이지의 계단 수치도 이 조건에서만 성립합니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>이 페이지의 수치는 <a href="#limits">보행별 한계</a>에 적은 조건의 계단 기준입니다.</p></div></div><h2 id="terms" tabindex="-1">용어 <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;용어 {#terms}&quot;">​</a></h2><figure><img style="max-width:100%;width:min(420px, 100%);height:auto;display:block;margin:1rem auto;" src="'+a+'" alt="계단 치수: A 단 높이, B 디딤판 깊이"><figcaption style="text-align:center;">[ A 단 높이 · B 디딤판 깊이 ]</figcaption></figure><table tabindex="0"><thead><tr><th></th><th>용어</th><th>뜻</th></tr></thead><tbody><tr><td>A</td><td>단 높이</td><td>한 디딤판에서 다음 디딤판까지의 수직 거리입니다. 연석이나 턱 하나도 한 단으로 봅니다.</td></tr><tr><td>B</td><td>디딤판 깊이</td><td>디딤판 하나의 앞뒤 길이로, 앞 모서리에서 뒤 끝(챌판이 있으면 챌판)까지 잽니다.</td></tr><tr><td></td><td>챌판</td><td>디딤판과 디딤판 사이를 막는 세로 판입니다.</td></tr><tr><td></td><td>챌판 없는 계단</td><td>챌판 없이 디딤판 사이가 뚫려 있는 계단입니다.</td></tr><tr><td></td><td>그레이팅 계단</td><td>디딤판이 아래가 비치는 금속 격자(그레이팅)로 된 계단입니다.</td></tr></tbody></table><h2 id="gaits" tabindex="-1">계단에서 쓰는 보행 <a class="header-anchor" href="#gaits" aria-label="Permalink to &quot;계단에서 쓰는 보행 {#gaits}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>고르는 것</th><th>걷는 보행</th><th>쓰는 카메라</th></tr></thead><tbody><tr><td><code>STAIRS</code></td><td>계단용으로 만든 계단 보행</td><td>몸체 아래 깊이 카메라 4대</td></tr><tr><td><code>WALK</code>, <code>Vision Walk</code> 켬(기본값)</td><td>학습 보행</td><td>같은 카메라</td></tr></tbody></table><h2 id="limits" tabindex="-1">보행별 한계 <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;보행별 한계 {#limits}&quot;">​</a></h2><p>다리형 RBQ10 기준 최대 단 높이입니다.</p><table tabindex="0"><thead><tr><th>보행</th><th>챌판 있는 계단(일반·그레이팅)</th><th>챌판 없는 계단</th></tr></thead><tbody><tr><td><code>STAIRS</code></td><td>최대 20 cm</td><td>최대 20 cm</td></tr><tr><td><code>WALK</code>(<code>Vision Walk</code> 켬)</td><td>최대 25 cm</td><td>쓸 수 없습니다</td></tr></tbody></table><ul><li>이 수치는 <strong>디딤판 깊이(B)가 단 높이(A)와 같은(1:1) 계단</strong>을 기준으로 정했습니다. 디딤판이 단 높이보다 깊은 계단(B &gt; A)에서도 같은 높이까지 쓸 수 있습니다.</li></ul>',12)])])}const _=d(i,[["render",s]]);export{u as __pageData,_ as default};
